algorithms.pseudocode:
function stereo_add(t, s):
    denom <- 1 - t*s
    if denom = 0: raise 'undefined on ts = 1'
    return (t + s) / denom

function compose_rotations(addresses):
    acc <- 0
    for t in addresses:
        acc <- stereo_add(acc, t)
    return acc

function project(t):
    d <- 1 + t*t
    return (2*t/d, (1 - t*t)/d)

function pythagorean_triples(limit):
    for q from 2 to limit:
        for p from 1 to q-1:
            if gcd(p, q) != 1: continue
            if (q - p) is even: continue   // need opposite parity
            a <- 2*p*q
            b <- q*q - p*p
            c <- p*p + q*q
            yield (min(a,b), max(a,b), c)
